// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeC = address(c).balance;
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 recordedAfterDeposit;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedAfterDeposit = __r; } catch { return; }
        bool withdrew;
        uint beforeC2 = address(c).balance;
        try c.withdrawBalance() {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        uint256 recordedAfterWithdraw;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedAfterWithdraw = __r; } catch { return; }
        uint afterC = address(c).balance;
        assertTrue((withdrew && recordedAfterWithdraw == 0 && beforeC2 - afterC >= recordedAfterDeposit) ||
            (!withdrew && recordedAfterWithdraw == recordedAfterDeposit && beforeC2 == afterC));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { }
}
